namespace snicholls::token {

    /// \brief Who stands behind a token on its chain.
    enum class issuance {
        native,  ///< the issuer's own deployment (Circle's USDC, Tether's USDT on Ethereum)
        bridged, ///< minted by a bridge against the token locked on another chain (USDT0, OP's bridged USDT)
        pegged,  ///< a third party's custodial token, backed by reserves it holds (Binance-Peg)
        wrapped  ///< a contract that wraps another asset (WETH, WBTC)
    };

} // namespace snicholls::token

